function evalTask(t,v){if(t.task_type==='classification')return{label_validity:typeof v?.label==='string',confidence:typeof v?.confidence==='number'&&v.confidence>=num(t.confidence_requirement,.6),consistency:!t.allowed_labels||t.allowed_labels.includes(v?.label)};if(t.task_type==='ranking'){const xs=arr(v?.items);return{ordering_validity:xs.every((x,i)=>!i||xs[i-1].score>=x.score),score_consistency:xs.every(x=>x.score>=0&&x.score<=100)}}if(t.task_type==='extraction')return{field_completeness:!arr(t.required_fields).some(k=>v?.fields?.[k]==null),format_correctness:true};if(t.task_type==='summarization')return{coverage:Boolean(v?.summary),unsupported_claims:!arr(v?.unsupported_claims).length,compression:t.source_length?v.summary.length<t.source_length:true};if(['generation','content_creation'].includes(t.task_type))return{instruction_following:v!=null,brand_fit:v?.brand_fit!==false,structure:typeof v==='object',duplication:v?.duplicate!==true};return{complete:v!=null&&JSON.stringify(v)!=='{}',consistent:true}}
export function computeConfidenceHeuristic({validation,evaluator_checks={},agreement=null,known_data_checks=null}={}){const s=[];if(validation)s.push(validation.ok?1:0);const x=Object.values(evaluator_checks).filter(v=>typeof v==='boolean');if(x.length)s.push(x.filter(Boolean).length/x.length);if(typeof agreement==='number')s.push(Math.max(0,Math.min(1,agreement)));if(typeof known_data_checks==='number')s.push(Math.max(0,Math.min(1,known_data_checks)));return{score:s.length?s.reduce((a,b)=>a+b,0)/s.length:0,heuristic:true,signals_used:s.length}}
export function runQualityGateV2(task,v,o={}){const validation=o.validation||parseValidateOutputV2(v,task),checks=evalTask(task,v),confidence=computeConfidenceHeuristic({validation,evaluator_checks:checks,agreement:o.agreement,known_data_checks:o.known_data_checks}),fail=Object.entries(checks).filter(([,x])=>x===false).map(([k])=>k),req=num(task.confidence_requirement,task.quality_level==='SOL'?.85:task.quality_level==='TERRA'?.7:.55);if(!validation.ok)fail.push('schema_valid');if(task.grounding_required&&o.grounding?.status!=='PASS')fail.push('grounding_requirement');if(confidence.score<req)fail.push('confidence_requirement');return{status:fail.length?'BLOCK':'PASS',checks:{schema_valid:validation.ok,...checks},failures:fail,confidence}}
