export function runOutputSafetyGate(out,p={}){const t=JSON.stringify(out??''),e=[];if(/sk-[A-Za-z0-9_-]{8,}|api[_-]?key\s*[:=]|password\s*[:=]|secret\s*[:=]/i.test(t))e.push('secret_leakage');if(p.personal_data_allowed!==true&&/[^\s@]+@[^\s@]+\.[^\s@]+/.test(t))e.push('personal_data_leakage');for(const x of arr(p.forbidden_terms))if(t.toLowerCase().includes(String(x).toLowerCase()))e.push('forbidden_action_or_claim');return{status:e.length?'BLOCK':'PASS',errors:e,delivery_allowed:!e.length}}

export async function evaluateGoldenSet(set=[],runner){const cases=[];for(const f of arr(set)){const r=await runner(clone(f.input),clone(f)),v=f.expected_schema?validateSchemaValue(r.output,f.expected_schema):{ok:true},props=arr(f.expected_properties).every(p=>path(r.output,p)!==undefined),exact=f.expected_output===undefined||JSON.stringify(r.output)===JSON.stringify(f.expected_output);cases.push({id:f.id,quality_pass:r.quality_pass!==false&&v.ok&&props&&exact,schema_pass:v.ok,latency_ms:num(r.latency_ms,0),cost_eur:num(r.cost_eur,null),failure:r.error||null})}const n=cases.length||1;return{ok:cases.every(x=>x.quality_pass),metrics:{quality_pass_rate:cases.filter(x=>x.quality_pass).length/n,schema_pass_rate:cases.filter(x=>x.schema_pass).length/n,average_latency_ms:cases.reduce((s,x)=>s+x.latency_ms,0)/n,average_cost_eur:cases.every(x=>x.cost_eur!==null)?cases.reduce((s,x)=>s+x.cost_eur,0)/n:null,failure_rate:cases.filter(x=>x.failure).length/n},cases}}
export function compareRegression(a={},b={}){const A=a.metrics||{},B=b.metrics||{},d={quality:num(B.quality_pass_rate,0)-num(A.quality_pass_rate,0),schema:num(B.schema_pass_rate,0)-num(A.schema_pass_rate,0),latency_ms:num(B.average_latency_ms,Infinity)-num(A.average_latency_ms,Infinity),failure_rate:num(B.failure_rate,1)-num(A.failure_rate,1),cost_eur:B.average_cost_eur==null||A.average_cost_eur==null?null:B.average_cost_eur-A.average_cost_eur};return{dimensions:d,candidate_better:d.quality>=0&&d.schema>=0&&d.failure_rate<=0&&(d.quality>0||d.schema>0||d.failure_rate<0||d.latency_ms<0||(d.cost_eur!==null&&d.cost_eur<0)),automatic_promotion:false}}
