export const buildBatchPlan=(records=[],o={})=>{const size=Math.max(1,Math.min(500,num(o.batch_size,100))),b=[];for(let i=0;i<records.length;i+=size)b.push({batch_id:`batch_${b.length+1}`,records:clone(records.slice(i,i+size))});return{batches:b,max_concurrency:Math.max(1,Math.min(16,num(o.max_concurrency,4))),partial_results:true,bounded:true}};
export async function runBatch(records,worker,o={}){const p=buildBatchPlan(records,o),results=[],failures=[];for(let i=0;i<p.batches.length;i+=p.max_concurrency){for(const r of await Promise.all(p.batches.slice(i,i+p.max_concurrency).map(async b=>{try{return{batch_id:b.batch_id,ok:true,result:await worker(b.records,b)}}catch(e){return{batch_id:b.batch_id,ok:false,error:str(e?.message||e,300)}}})))(r.ok?results:failures).push(r)}return{ok:!failures.length,results,failures,aggregate:{batches:p.batches.length,completed:results.length,failed:failures.length},bounded_concurrency:p.max_concurrency}}
