export async function runBoundedAgent(a,h={}){const start=Date.now(),steps=[];let cost=0;for(let i=0;i<a.max_steps;i++){if(Date.now()-start>=a.max_duration_ms)return{ok:false,status:'STOPPED',reason:'max_duration',steps,cost_eur:cost};const p=await h.planner?.({agent:a,steps:clone(steps),index:i})||{action:'terminate'};if(p.action==='terminate')return{ok:true,status:'COMPLETED',reason:p.reason||'termination_condition',steps,cost_eur:cost};if(!a.available_tools.includes(p.tool_id))return{ok:false,status:'STOPPED',reason:'tool_not_allowed',steps,cost_eur:cost};if(p.side_effect_class&&p.side_effect_class!=='read_only'&&!a.allowed_side_effects.includes(p.side_effect_class))return{ok:false,status:'STOPPED',reason:'side_effect_not_allowed',steps,cost_eur:cost};const r=await h.executor?.(p)||{ok:false};cost+=Math.max(0,num(r.cost_eur,0));steps.push({index:i+1,plan:clone(p),result:clone(r)});if(cost>a.max_cost_eur)return{ok:false,status:'STOPPED',reason:'max_cost',steps,cost_eur:cost};if(r.terminate)return{ok:r.ok!==false,status:r.ok===false?'FAILED':'COMPLETED',reason:r.reason||'executor_terminate',steps,cost_eur:cost}}return{ok:false,status:'STOPPED',reason:'max_steps',steps,cost_eur:cost}}
