export function classifyFailure(e={}){const c=str(e.code||e.error||e.message,200).toLowerCase();const map=[['provider_timeout',/timeout/],['rate_limit',/rate/],['auth_failure',/auth|credential/],['schema_failure',/schema/],['quality_failure',/quality/],['context_missing',/context.*missing/],['context_too_large',/context.*large/],['tool_failure',/tool/],['retrieval_failure',/retriev/],['budget_exceeded',/budget|cost/],['policy_block',/policy|blocked/],['model_unavailable',/unavailable/]];const type=map.find(([,r])=>r.test(c))?.[0]||'invalid_output';return{type,retryable:['provider_timeout','rate_limit','invalid_output','schema_failure','quality_failure'].includes(type)}}
export function planRecovery(f,p={}){const a=[];if(['invalid_output','schema_failure'].includes(f.type)&&p.repair_allowed!==false)a.push('REPAIR');if(f.retryable&&num(p.retry_count,0)<num(p.max_retries,1))a.push('RETRY');if(['quality_failure','model_unavailable'].includes(f.type)&&p.model_change_allowed!==false)a.push('FALLBACK_MODEL');if(['provider_timeout','rate_limit','auth_failure'].includes(f.type)&&p.provider_fallback_allowed!==false)a.push('FALLBACK_PROVIDER');if(!a.length||p.high_impact)a.push(p.human_review_allowed!==false?'HUMAN_REVIEW':'TERMINATE');return{contract:'riosystems.ai-recovery.v2',failure_type:f.type,actions:a,bounded:true}}
export function createCircuitBreaker(o={}){let state='CLOSED',fails=0,opened=0;const n=Math.max(1,num(o.failure_threshold,3)),ms=Math.max(100,num(o.reset_after_ms,1000));return{state:()=>state,allow(){if(state==='OPEN'&&Date.now()-opened>=ms)state='HALF_OPEN';return state!=='OPEN'},success(){state='CLOSED';fails=0},failure(){if(++fails>=n){state='OPEN';opened=Date.now()}return state},snapshot:()=>({state,failures:fails})}}
