async function timeout(p,ms=30000){let id;try{return await Promise.race([p,new Promise((_,rej)=>{id=setTimeout(()=>rej(Object.assign(new Error('provider_timeout'),{code:'provider_timeout'})),Math.max(100,ms))})])}finally{clearTimeout(id)}}
